(() => {
  const apply = () => {
    const card = document.querySelector('[data-name="tp link tapo p110m enchufe inteligente matter energia"]');
    if (!card) return;
    const link = card.querySelector('.offer-button');
    if (link) link.href = 'https://amzn.to/4AfzgB2';
    const art = card.querySelector('.product-art');
    if (art) {
      art.style.cssText = 'display:flex;align-items:center;justify-content:center;padding:0;background:#fff;overflow:hidden;';
      art.innerHTML = '<img src="data:image/jpeg;base64," alt="TP-Link Tapo P110M Enchufe Inteligente Matter" loading="lazy" style="width:auto;height:auto;max-width:82%;max-height:82%;object-fit:contain;display:block;margin:auto">';
      art.removeAttribute('aria-hidden');
      art.setAttribute('role','img');
      art.setAttribute('aria-label','TP-Link Tapo P110M Enchufe Inteligente Matter');
    }
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', apply, { once: true });
  } else {
    apply();
  }
})();